38class Issue {
39
40    // store book issued by student
41    HashMap<Integer, String> issue = new HashMap<>();
42
43    Scanner input = new Scanner(System.in);
44
45    Book b1 = new Book();
46    Student s1 = new Student();
47
48    public Issue() {
49
50        // add elements to student HashMap
51        s1.add();
52
53        // add elements to book HashMap
54        b1.add();
55    }
56
57    // method to issue book
58    void issueBook(int id) {
59
60        System.out.println("enter a book");
61        String bookName = input.nextLine();
62
63        // check if book is inside the book hashmap
64        if (b1.book.containsValue(bookName)) {
65
66            // get book id to remove it from the book HashMap
67            int bookId = 0;
68            // iterate each entry of hashmap
69            for (Entry<Integer, String> entry : b1.book.entrySet()) {
70
71                // if give value is equal to value from entry
72                // print the corresponding key
73                if (entry.getValue().equals(bookName)) {
74                    bookId = entry.getKey();
75                    break;
76                }
77            }
78
79            // add value of student id and book to issue hashmap
80            issue.put(id, bookName);
81
82            // remove book from the book hashmap
83            b1.book.remove(bookId);
84
85            // get student name from id
86            String name = s1.student.get(id);
87            // print name and issued book
88            System.out.println("Name: " + name);
89            System.out.println("Book: " + bookName);
90            System.out.println("Book issued Congratulation");
91        }
92
93        else {
94            System.out.println("Book doesn't exist");
95            System.out.println("We have following Books:");
96            System.out.println(b1.book);
97        }
98
99    }
