118                    bookId = entry.getKey();
119                    break;
120                }
121            }
122
123            // check if book is issued
124            if (issue.containsValue(bookName)) {
125
126                // remove issue record form issue HashMap
127                issue.remove(id);
128
129                // add book back to book hashmap
130                b1.book.put(bookId, bookName);
131
132                // print name of student and book
